def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    # 0/1 knapsack: maximize value within time limit T
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        # iterate backwards to avoid reuse of the same herb
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val
    return dp[T]

def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Ensure we only consider the first n items (in case the list is longer)
    items = volumes[:n]
    # DP array where dp[s] is True if sum s is achievable
    dp = [False] * (V + 1)
    dp[0] = True
    for vol in items:
        if vol > V:
            continue
        # iterate backwards to avoid reuse of the same item
        for s in range(V, vol - 1, -1):
            if dp[s - vol]:
                dp[s] = True
    # Find the largest achievable sum <= V
    max_sum = max(s for s, achievable in enumerate(dp) if achievable)
    return V - max_sum

def find_most_unhappy_day(schedule) -> int:
    max_unhappy = 0
    best_day = 0
    for i, (school, extra) in enumerate(schedule, start=1):
        total = school + extra
        if total > 8:
            unhappy = total - 8
            if unhappy > max_unhappy:
                max_unhappy = unhappy
                best_day = i
    return best_day if max_unhappy > 0 else 0

def minimum_students_to_leave(heights):
    n = len(heights)
    if n <= 1:
        return 0
    # Longest strictly increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        hi = heights[i]
        best = 0
        for j in range(i):
            if heights[j] < hi and lis[j] > best:
                best = lis[j]
        lis[i] = best + 1
    # Longest strictly decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        hi = heights[i]
        best = 0
        for j in range(i + 1, n):
            if heights[j] < hi and lds[j] > best:
                best = lds[j]
        lds[i] = best + 1
    # Find maximum bitonic subsequence length
    max_len = 0
    for i in range(n):
        cur = lis[i] + lds[i] - 1
        if cur > max_len:
            max_len = cur
    return n - max_len
